<?php require_role('lawyer');$s=db()->prepare('SELECT c.*,u.full_name client FROM cases c JOIN users u ON u.id=c.client_id WHERE c.lawyer_id=?');$s->execute([user()['id']]);$cases=$s->fetchAll();$title='Lawyer Dashboard';include '../../includes/header.php';?><h1>Lawyer Dashboard</h1><div class="card"><h2>Assigned cases</h2><table class="table"><tr><th>Title</th><th>Client</th><th>Status</th></tr><?php foreach($cases as $c):?><tr><td><?=e($c['title'])?></td><td><?=e($c['client'])?></td><td><?=e($c['status'])?></td></tr><?php endforeach;?></table><p>Authorized PDF document uploads can be added through the case file module.</p></div><?php include '../../includes/footer.php';
